-- Carga inicial del catálogo (Walt Disney World y Universal Orlando, octubre de 2026).
-- Alturas y cierres tomados de las fuentes publicadas a esa fecha; quedan "sin revisar" hasta que un
-- administrador de la plataforma los verifique contra las páginas oficiales.
ON CONFLICT ("destination", "area", "name") DO NOTHING;

-- Imperdibles de cada parque: se suman siempre a la propuesta de itinerario. Los administradores los ajustan.
UPDATE "CatalogEntry" SET "mustDo" = true WHERE "area" = 'Magic Kingdom' AND "name" IN ('Seven Dwarfs Mine Train', 'Peter Pan''s Flight', 'Haunted Mansion', 'Pirates of the Caribbean', 'Space Mountain', 'Happily Ever After');
UPDATE "CatalogEntry" SET "mustDo" = true WHERE "area" = 'EPCOT' AND "name" IN ('Frozen Ever After', 'Remy''s Ratatouille Adventure', 'Guardians of the Galaxy: Cosmic Rewind', 'Soarin''', 'Test Track', 'Luminous The Symphony of Us');
UPDATE "CatalogEntry" SET "mustDo" = true WHERE "area" = 'Hollywood Studios' AND "name" IN ('Star Wars: Rise of the Resistance', 'Slinky Dog Dash', 'Mickey & Minnie''s Runaway Railway', 'Toy Story Mania!', 'The Twilight Zone Tower of Terror', 'Fantasmic!');
UPDATE "CatalogEntry" SET "mustDo" = true WHERE "area" = 'Animal Kingdom' AND "name" IN ('Avatar Flight of Passage', 'Na''vi River Journey', 'Kilimanjaro Safaris', 'Expedition Everest – Legend of the Forbidden Mountain', 'Festival of the Lion King');
UPDATE "CatalogEntry" SET "mustDo" = true WHERE "area" = 'Universal Studios Florida' AND "name" IN ('Harry Potter and the Escape from Gringotts', 'Hogwarts Express – King''s Cross Station', 'Revenge of the Mummy', 'Despicable Me Minion Mayhem', 'MEN IN BLACK Alien Attack');
UPDATE "CatalogEntry" SET "mustDo" = true WHERE "area" = 'Islands of Adventure' AND "name" IN ('Hagrid''s Magical Creatures Motorbike Adventure', 'Harry Potter and the Forbidden Journey', 'Jurassic World VelociCoaster', 'The Amazing Adventures of Spider-Man', 'Skull Island: Reign of Kong');
UPDATE "CatalogEntry" SET "mustDo" = true WHERE "area" = 'Epic Universe' AND "name" IN ('Harry Potter and the Battle at the Ministry', 'Mario Kart: Bowser''s Challenge', 'Stardust Racers', 'Hiccup''s Wing Gliders', 'Monsters Unchained: The Frankenstein Experiment');
